    ler_arquivo("produtos.txt", produtos, &tam_produtos);
    ler_arquivo("vendas.txt", vendas, &tam_vendas);

    // 1) Acumula vendas por produto
    for (int i = 0; i < tam_produtos; i++) {
        produtos[i].qtd_vendida = 0;
        for (int j = 0; j < tam_vendas; j++) {
            if (vendas[j].codigo_produto == produtos[i].codigo_produto)
                produtos[i].qtd_vendida += vendas[j].quantidade_vendida;
        }
    }

    // 2) Calcula necessidade e transferência corretamente
    for (int i = 0; i < tam_produtos; i++) {
        // Estoque efetivo após as vendas do período
        int estoque_efetivo = produtos[i].qtd_estoque - produtos[i].qtd_vendida;

        // Quanto falta para atingir o mínimo?
        int necessidade = produtos[i].qtd_minima - estoque_efetivo;
        if (necessidade < 0) necessidade = 0;

        produtos[i].necessidade_transferencia = necessidade;

        // Quanto dessa necessidade será atendido por venda interna?
        int vendendo_para_cobrir = min(produtos[i].qtd_vendida, necessidade);
        produtos[i].qtd_transferencia = necessidade - vendendo_para_cobrir;
        if (produtos[i].qtd_transferencia < 0) produtos[i].qtd_transferencia = 0;
    }

    // 3) Escreve TRANSFERE.txt
    FILE *saida = fopen("TRANSFERE.txt", "w");
    if (!saida) { printf("Erro ao criar TRANSFERE.txt\n"); return 1; }

    fprintf(saida, "Produto\tQtCO\tQtMin\tQtVendas\tEstq.após\tNecess.\tTransf.de Vendas\tArm p/ CO\n");
    for (int i = 0; i < tam_produtos; i++) {
        int estq_apos = produtos[i].qtd_estoque - produtos[i].qtd_vendida;
        fprintf(saida,
                "%05d|%03d|%03d|%03d|%03d|%03d|%03d|%03d\n",
                produtos[i].codigo_produto,
                produtos[i].qtd_estoque,
                produtos[i].qtd_minima,
                produtos[i].qtd_vendida,
                estq_apos,
                produtos[i].necessidade_transferencia,
                produtos[i].qtd_transferencia,
                produtos[i].qtd_transferencia); // mesma coluna pro exemplo
    }
    fclose(saida);

    // 4) Escreve divergências
    FILE *div = fopen("divergencias.txt", "w");
    if (!div) { printf("Erro ao criar divergencias.txt\n"); return 1; }

    for (int i = 0; i < tam_vendas; i++) {
        for (int j = 0; j < tam_produtos; j++) {
            if (vendas[i].codigo_produto == produtos[j].codigo_produto) {
                // Estoque insuficiente para atender a venda
                if (vendas[i].quantidade_vendida > produtos[j].qtd_estoque) {
                    fprintf(div,
                            "Produto %05d: venda de %03d unidades com estoque insuficiente (%03d unidades)\n",
                            vendas[i].codigo_produto,
                            vendas[i].quantidade_vendida,
                            produtos[j].qtd_estoque);
                }
                // Situação de venda inválida (ajuste conforme sua regra real)
                if (vendas[i].situacao_venda < 1 || vendas[i].situacao_venda > 4) {
                    fprintf(div,
                            "Produto %05d: situacao_venda invalida (%d) na venda de %03d unidades\n",
                            vendas[i].codigo_produto,
                            vendas[i].situacao_venda,
                            vendas[i].quantidade_vendida);
                }
            }
        }
    }
    fclose(div);

    printf("Processamento concluído!\n");
    printf("Gerados: TRANSFERE.txt e divergencias.txt\n");

    free(produtos);
    free(vendas);
    return 0;
}
